1256:     private void startWatchdog(Session s) {
1257:         Thread.ofPlatform().daemon(true).name("live-session-watchdog").start(() -> {
1258:             long before = System.nanoTime(); Instant wall = clock.instant();
1259:             while (!s.finished && s.stopReason == null) {
1260:                 try { Thread.sleep(200); } catch (InterruptedException ignored) { Thread.currentThread().interrupt(); return; }
1261:                 if (s.finished || s.stopReason != null) return;
1262:                 long now = System.nanoTime(); Instant next = clock.instant();
1263:                 long monotonic = TimeUnit.NANOSECONDS.toMillis(now - before);
1264:                 if (monotonic > 2500 || Math.abs(Duration.between(wall, next).toMillis() - monotonic) > 2000) {
1265:                     s.stopAll("STOPPED_INTERRUPTED");
1266:                     supervisor.stopCampaign(s.manifest.campaignId(), LiveProviderSession.ENDPOINTS);
1267:                     return;
1268:                 }
1269:                 before = now; wall = next;
1270:             }
1271:         });
1272:     }
